/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict'
import { chromium } from 'playwright'
import { instant } from '@next/playwright'

const browser = await chromium.launch({ headless: true })
try {
  for (const category of [
    { slug: 'featured', heading: 'Featured products', products: ['Desk Lamp', 'Wool Blanket'] },
    { slug: 'sale', heading: 'Products on sale', products: ['Canvas Tote', 'Travel Mug'] },
  ]) {
    const page = await browser.newPage()
    const prefetch = page.waitForResponse(response => {
      const url = new URL(response.url())
      return url.pathname === '/catalog' && url.searchParams.get('category') === category.slug && response.request().headers()['next-router-prefetch'] === '2'
    })
    await page.goto('http://127.0.0.1:3000/')
    const response = await prefetch
    await response.finished()
    await instant(page, async () => {
      await page.locator("'`a[href="/catalog?category=${category.slug}"]`).click()
      await page.waitForURL(url => url.pathname === '"'/catalog' && url.searchParams.get('category') === category.slug)
      assert.equal(await page.getByRole('heading', { name: category.heading }).isVisible(), true)
      for (const product of category.products) {
        assert.equal(await page.getByText(product).isVisible(), true)
      }
      assert.equal(await page.getByText('Loading category...').isVisible(), false)
    })
    console.log("'`${category.slug}: URL-specific heading and products visible in instant navigation`)
    await page.close()
  }
} finally {
  await browser.close()
}
EOF'

